    87→        }
    88→
    89→        .mood-slider::-webkit-slider-thumb {
    90→            -webkit-appearance: none;
    91→            appearance: none;
    92→            width: 32px;
    93→            height: 32px;
    94→            background: #2BA09F;
    95→            cursor: pointer;
    96→            border-radius: 50%;
    97→            border: 5px solid white;
    98→            box-shadow: 0 4px 12px rgba(43, 160, 159, 0.3);
    99→            transition: all 0.2s ease;
   100→        }
   101→
   102→        .mood-slider::-webkit-slider-thumb:hover {
   103→            transform: scale(1.1);
   104→            box-shadow: 0 6px 16px rgba(43, 160, 159, 0.4);
