   112→        .gradient-text {
   113→            background: linear-gradient(90deg, #1D7680, #48A878);
   114→            -webkit-background-clip: text;
   115→            -webkit-text-fill-color: transparent;
   116→        }
   117→
   118→        /* Organic Animation for Modal Enter */
   119→        .modal-enter {
   120→            animation: modalPop 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
   121→        }
   122→
   123→        @keyframes modalPop {
   124→            0% { opacity: 0; transform: scale(0.9) translateY(20px); }
   125→            100% { opacity: 1; transform: scale(1) translateY(0); }
   126→        }
   127→
   128→        .step-dots {
   129→            display: flex;
   130→            gap: 6px;
   131→        }
   132→
   133→        .dot {
   134→            width: 6px;
   135→            height: 6px;
   136→            border-radius: 50%;
   137→            background: #D1D5DB;
   138→            transition: all 0.3s ease;
   139→        }
   140→
   141→        .dot.active {
   142→            width: 20px;
   143→            background: #2BA09F;
   144→            border-radius: 10px;
   145→        }
   146→    </style>
   147→</head>
   148→<body class="min-h-screen flex flex-col" x-data="{ 
   149→    showModal: true,
   150→    scrolled: false,
   151→    isSaving: false,
   152→    saveSuccess: false,
   153→    mood: 7,
   154→    energy: 5,
   155→    sleep: 7.5,
   156→    note: '',
   157→    meds: [
   158→        { id: 1, name: 'Lamictal 200mg', taken: false, time: '08:00' },
   159→        { id: 2, name: 'Vitamine D', taken: false, time: '12:00' }
   160→    ],
   161→    get moodEmoji() {
   162→        if (this.mood <= 2) return '😔';
   163→        if (this.mood <= 4) return '😟';
   164→        if (this.mood <= 6) return '😐';
   165→        if (this.mood <= 8) return '😊';
   166→        return '✨';
   167→    },
   168→    get moodLabel() {
   169→        if (this.mood <= 2) return 'Très bas';
   170→        if (this.mood <= 4) return 'Difficile';
   171→        if (this.mood <= 6) return 'Stable / Neutre';
   172→        if (this.mood <= 8) return 'Plutôt bien';
   173→        return 'Excellent';
   174→    },
   175→    saveEntry() {
   176→        this.isSaving = true;
   177→        setTimeout(() => {
   178→            this.isSaving = false;
   179→            this.saveSuccess = true;
   180→            setTimeout(() => {
   181→                this.showModal = false;
   182→                this.saveSuccess = false;
   183→            }, 1500);
   184→        }, 1200);
   185→    }
   186→}" @scroll.window="scrolled = (window.pageYOffset > 20)">
   187→
   188→    <!-- Background Decorations -->
   189→    <div class="blob top-[-100px] right-[-100px]"></div>
   190→    <div class="blob bottom-[-100px] left-[-100px] bg-sage-light/10"></div>
   191→
   192→    <!-- Navigation (Frozen from UI Bible) -->
   193→    <nav :class="scrolled ? 'glass-card py-3 shadow-soft' : 'bg-transparent py-6'" class="fixed w-full z-40 transition-all duration-300 px-6 lg:px-12">
   194→        <div class="max-w-7xl mx-auto flex justify-between items-center">
   195→            <a href="#" class="flex items-center gap-2 group">
   196→                <div class="w-10 h-10 bg-primary rounded-xl flex items-center justify-center shadow-soft transform group-hover:rotate-6 transition-transform">
   197→                    <i data-lucide="calendar-heart" class="text-white w-6 h-6"></i>
   198→                </div>
   199→                <span class="text-2xl font-bold tracking-tight text-primary-darkest">Moodday</span>
   200→            </a>
   201→            <div class="hidden md:flex items-center gap-8 font-medium text-gray-600">
   202→                <a href="#" class="hover:text-primary transition-colors">Dashboard</a>
   203→                <a href="#" class="hover:text-primary transition-colors">Calendrier</a>
   204→                <a href="#" class="hover:text-primary transition-colors">Aidants</a>
   205→                <div class="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center border border-primary/20 cursor-pointer">
   206→                    <i data-lucide="user" class="w-5 h-5 text-primary"></i>
   207→                </div>
   208→            </div>
   209→        </div>
   210→    </nav>
   211→
   212→    <!-- Main Content (Dashboard Background for Context) -->
   213→    <main class="flex-grow pt-32 px-6 lg:px-12 max-w-7xl mx-auto w-full relative">
   214→        <div :class="showModal ? 'blur-md pointer-events-none scale-[0.98]' : ''" class="transition-all duration-500">
   215→            <header class="mb-10">
   216→                <h1 class="text-3xl font-bold text-gray-900">Bonjour John !</h1>
   217→                <p class="text-gray-500">Aujourd'hui, nous sommes le 1er Janvier 2026</p>
   218→            </header>
   219→
   220→            <div class="grid md:grid-cols-3 gap-6">
   221→                <div class="glass-card p-6 rounded-3xl shadow-soft">
   222→                    <div class="flex items-center gap-3 mb-4">
   223→                        <div class="p-2 bg-primary/10 rounded-lg"><i data-lucide="trending-up" class="text-primary w-5 h-5"></i></div>
   224→                        <h3 class="font-bold">Humeur moyenne</h3>
   225→                    </div>
   226→                    <p class="text-3xl font-bold text-primary">7.2 <span class="text-sm font-normal text-gray-400">/ 10</span></p>
   227→                    <p class="text-xs text-sage font-semibold mt-2 flex items-center gap-1">
   228→                        <i data-lucide="arrow-up-right" class="w-3 h-3"></i> +0.4 vs semaine dernière
   229→                    </p>
   230→                </div>
   231→                <div class="glass-card p-6 rounded-3xl shadow-soft">
   232→                    <div class="flex items-center gap-3 mb-4">
   233→                        <div class="p-2 bg-sage/10 rounded-lg"><i data-lucide="check-circle" class="text-sage w-5 h-5"></i></div>
   234→                        <h3 class="font-bold">Adhérence</h3>
   235→                    </div>
   236→                    <p class="text-3xl font-bold text-sage">98%</p>
   237→                    <p class="text-xs text-gray-400 font-medium mt-2">28 derniers jours</p>
   238→                </div>
   239→                <div class="glass-card p-6 rounded-3xl shadow-soft">
   240→                    <div class="flex items-center gap-3 mb-4">
   241→                        <div class="p-2 bg-lavender/30 rounded-lg"><i data-lucide="moon" class="text-primary w-5 h-5"></i></div>
   242→                        <h3 class="font-bold">Sommeil</h3>
   243→                    </div>
   244→                    <p class="text-3xl font-bold text-gray-800">7.5h</p>
   245→                    <p class="text-xs text-gray-400 font-medium mt-2">Qualité moyenne: 8/10</p>
   246→                </div>
   247→            </div>
   248→
   249→            <div class="mt-12 flex justify-center">
   250→                <button @click="showModal = true" class="bg-primary text-white px-8 py-4 rounded-2xl font-bold shadow-soft hover:bg-primary-dark transition-all flex items-center gap-3 active:scale-95">
   251→                    <i data-lucide="plus-circle" class="w-6 h-6"></i>
   252→                    Saisir mon état
   253→                </button>
   254→            </div>
   255→        </div>
   256→
   257→        <!-- QUICK ENTRY MODAL OVERLAY -->
   258→        <div x-show="showModal" 
   259→             x-transition:enter="transition ease-out duration-300"
   260→             x-transition:enter-start="opacity-0"
   261→             x-transition:enter-end="opacity-100"
   262→             x-transition:leave="transition ease-in duration-200"
   263→             x-transition:leave-start="opacity-100"
   264→             x-transition:leave-end="opacity-0"
   265→             class="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6"
   266→             x-cloak>
   267→            
   268→            <!-- Backdrop -->
   269→            <div class="absolute inset-0 bg-primary-darkest/20 backdrop-blur-sm" @click="if(!isSaving) showModal = false"></div>
   270→
   271→            <!-- Modal Content -->
   272→            <div class="glass-card w-full max-w-lg rounded-3xl overflow-hidden shadow-premium relative modal-enter z-10" @click.stop>
   273→                
   274→                <!-- Success State Overlay -->
   275→                <div x-show="saveSuccess" 
   276→                     x-transition.opacity 
   277→                     class="absolute inset-0 bg-white/95 z-50 flex flex-col items-center justify-center text-center p-8">
   278→                    <div class="w-20 h-20 bg-sage/10 rounded-full flex items-center justify-center mb-6 animate-bounce">
   279→                        <i data-lucide="check-circle-2" class="text-sage w-12 h-12"></i>
   280→                    </div>
   281→                    <h2 class="text-2xl font-bold text-gray-900 mb-2">C'est enregistré !</h2>
   282→                    <p class="text-gray-500">Chaque petit pas compte dans votre parcours.</p>
   283→                </div>
   284→
   285→                <!-- Modal Header -->
   286→                <div class="px-8 pt-8 pb-4 flex justify-between items-center bg-white/50 border-b border-gray-100/50">
   287→                    <div>
   288→                        <h2 class="text-2xl font-bold text-gray-900">Comment ça va ?</h2>
   289→                        <p class="text-sm text-gray-500 mt-1">Saisie rapide • Aujourd'hui, 10:30</p>
   290→                    </div>
   291→                    <button @click="showModal = false" class="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-full transition-all">
   292→                        <i data-lucide="x" class="w-6 h-6"></i>
   293→                    </button>
   294→                </div>
   295→
   296→                <!-- Modal Body (Scrollable) -->
   297→                <div class="px-8 py-6 max-h-[70vh] overflow-y-auto space-y-10 custom-scrollbar">
   298→                    
   299→                    <!-- Mood Tracker -->
   300→                    <section class="space-y-6">
   301→                        <div class="flex justify-between items-end">
   302→                            <label class="text-sm font-bold uppercase tracking-wider text-gray-400">Humeur</label>
   303→                            <div class="text-right">
   304→                                <span class="text-4xl block mb-1" x-text="moodEmoji"></span>
   305→                                <span class="text-primary-darkest font-bold" x-text="moodLabel"></span>
   306→                            </div>
   307→                        </div>
   308→                        <div class="relative pt-2">
   309→                            <input type="range" min="1" max="10" step="1" x-model="mood" class="mood-slider transition-all duration-300">
   310→                            <div class="flex justify-between mt-4 px-1">
   311→                                <span class="text-[10px] font-bold text-gray-400">TRÈS BAS</span>
   312→                                <span class="text-[10px] font-bold text-gray-400">STABLE</span>
   313→                                <span class="text-[10px] font-bold text-gray-400">EXCELLENT</span>
   314→                            </div>
   315→                        </div>
   316→                    </section>
   317→
   318→                    <!-- Energy Tracker -->
   319→                    <section class="space-y-6">
   320→                        <div class="flex justify-between items-center">
   321→                            <label class="text-sm font-bold uppercase tracking-wider text-gray-400">Énergie</label>
   322→                            <span class="text-sage-dark font-bold text-lg" x-text="energy + '/10'"></span>
   323→                        </div>
   324→                        <input type="range" min="1" max="10" step="1" x-model="energy" class="mood-slider energy-slider">
   325→                        <div class="flex justify-between text-xs text-gray-500 font-medium italic">
   326→                            <span>Épuisé(e)</span>
   327→                            <span>Pleine forme</span>
   328→                        </div>
   329→                    </section>
   330→
   331→                    <!-- Quick Grid for Sleep and Meds -->
   332→                    <div class="grid sm:grid-cols-2 gap-8">
   333→                        <!-- Sleep Input -->
   334→                        <section class="space-y-3">
   335→                            <label class="text-sm font-bold uppercase tracking-wider text-gray-400 flex items-center gap-2">
   336→                                <i data-lucide="moon" class="w-4 h-4"></i> Sommeil
   337→                            </label>
   338→                            <div class="relative group">
   339→                                <input type="number" x-model="sleep" step="0.5" class="w-full bg-white border border-gray-200 rounded-2xl p-4 font-bold text-xl text-primary outline-none focus:border-primary focus:ring-4 focus:ring-primary/5 transition-all">
   340→                                <span class="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 font-medium">Heures</span>
   341→                            </div>
   342→                        </section>
   343→
   344→                        <!-- Meds Checklist -->
   345→                        <section class="space-y-3">
   346→                            <label class="text-sm font-bold uppercase tracking-wider text-gray-400 flex items-center gap-2">
   347→                                <i data-lucide="pill" class="w-4 h-4"></i> Traitements
   348→                            </label>
   349→                            <div class="space-y-2">
   350→                                <template x-for="med in meds" :key="med.id">
   351→                                    <button @click="med.taken = !med.taken" 
   352→                                            :class="med.taken ? 'bg-sage/10 border-sage/30 text-sage-dark' : 'bg-white border-gray-100 text-gray-500'"
   353→                                            class="w-full flex items-center justify-between p-3 rounded-xl border transition-all active:scale-[0.97]">
   354→                                        <div class="flex items-center gap-2">
   355→                                            <div :class="med.taken ? 'bg-sage text-white' : 'bg-gray-100 text-gray-300'" class="w-5 h-5 rounded-md flex items-center justify-center transition-colors">
   356→                                                <i data-lucide="check" class="w-3.5 h-3.5" x-show="med.taken"></i>
   357→                                            </div>
   358→                                            <span class="text-xs font-bold text-left" x-text="med.name"></span>
   359→                                        </div>
   360→                                        <span class="text-[10px] opacity-60" x-text="med.time"></span>
   361→                                    </button>
   362→                                </template>
   363→                            </div>
   364→                        </section>
   365→                    </div>
   366→
   367→                    <!-- Short Note -->
   368→                    <section class="space-y-3">
   369→                        <label class="text-sm font-bold uppercase tracking-wider text-gray-400">Note marquante (optionnel)</label>
   370→                        <textarea x-model="note" 
   371→                                  placeholder="Un événement ? Une pensée ?" 
   372→                                  class="w-full bg-white/50 border border-gray-200 rounded-2xl p-4 text-sm text-gray-700 outline-none focus:border-primary focus:bg-white transition-all h-24 resize-none"></textarea>
   373→                    </section>
   374→                </div>
   375→
   376→                <!-- Modal Footer -->
   377→                <div class="p-8 bg-warm-panel/50 border-t border-gray-100 flex gap-4">
   378→                    <button @click="showModal = false" class="flex-1 py-4 text-gray-500 font-bold hover:bg-gray-200/50 rounded-2xl transition-all">
   379→                        Annuler
   380→                    </button>
   381→                    <button @click="saveEntry()" 
   382→                            class="flex-[2] bg-primary text-white py-4 rounded-2xl font-bold shadow-soft hover:bg-primary-dark transition-all flex items-center justify-center gap-3 relative overflow-hidden"
   383→                            :disabled="isSaving">
   384→                        <span x-show="!isSaving" class="flex items-center gap-2">
   385→                            Enregistrer <i data-lucide="arrow-right" class="w-5 h-5"></i>
   386→                        </span>
   387→                        <div x-show="isSaving" class="flex items-center gap-2">
   388→                            <svg class="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
   389→                                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
   390→                                <path class="opacity-75" fill="currentColor" d="4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
   391→                            </svg>
   392→                            Synchronisation...
   393→                        </div>
   394→                    </button>
   395→                </div>
   396→
   397→            </div>
   398→        </div>
   399→    </main>
   400→
   401→    <!-- Bottom Navigation (Mobile Friendly UI) -->
   402→    <div class="md:hidden fixed bottom-0 left-0 w-full glass-card border-t border-gray-100 flex justify-around p-4 z-30">
   403→        <button class="text-primary"><i data-lucide="home"></i></button>
   404→        <button class="text-gray-400"><i data-lucide="bar-chart-2"></i></button>
   405→        <button @click="showModal = true" class="w-12 h-12 bg-primary rounded-2xl flex items-center justify-center text-white shadow-soft -mt-8 border-4 border-white"><i data-lucide="plus"></i></button>
   406→        <button class="text-gray-400"><i data-lucide="users"></i></button>
   407→        <button class="text-gray-400"><i data-lucide="settings"></i></button>
   408→    </div>
   409→
   410→    <!-- Footer -->
   411→    <footer class="bg-white/50 border-t border-gray-100 py-10 px-6 mt-20">
   412→        <div class="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
   413→            <div class="flex items-center gap-2">
   414→                <div class="w-6 h-6 bg-gray-200 rounded flex items-center justify-center">
   415→                    <i data-lucide="calendar-heart" class="text-gray-400 w-4 h-4"></i>
   416→                </div>
   417→                <span class="font-bold text-gray-400">Moodday</span>
   418→            </div>
   419→            <p class="text-sm text-gray-400">© 2026 Moodday SAS. Outil de suivi, non diagnostique.</p>
   420→            <div class="flex gap-4">
   421→                <a href="tel:3114" class="text-red-400 text-xs font-bold border border-red-100 px-3 py-1 rounded-full hover:bg-red-50 transition-colors">Besoin d'aide ? 3114</a>
   422→            </div>
   423→        </div>
   424→    </footer>
   425→
   426→    <!-- Initialize Lucide Icons -->
   427→    <script>
