   570→  background-color: var(--shiki-dark-bg) !important;
   571→  /* Optional, if you also want font styles */
   572→  font-style: var(--shiki-dark-font-style) !important;
   573→  font-weight: var(--shiki-dark-font-weight) !important;
   574→  text-decoration: var(--shiki-dark-text-decoration) !important;
   575→}
   576→
   577→.prose {
   578→  code:not(pre code) {
