     3→import { createFormHook, createFormHookContexts } from "@tanstack/react-form";
     4→import type * as React from "react";
     5→import type { z } from "zod";
     6→
     7→import type { Button } from "@/components/ui/button";
     8→import { Checkbox } from "@/components/ui/checkbox";
     9→import {
    10→  Field,
    11→  FieldContent,
    12→  FieldDescription as FieldDescriptionComponent,
    13→  FieldError,
    14→  FieldLabel as FieldLabelComponent,
    15→} from "@/components/ui/field";
    16→import { Input } from "@/components/ui/input";
    17→import { Select } from "@/components/ui/select";
    18→import { Switch } from "@/components/ui/switch";
    19→import { Textarea } from "@/components/ui/textarea";
    20→import { LoadingButton } from "./submit-button";
    21→
    22→/**
    23→ * TanStack Form context exports for advanced field/form access
    24→ *
    25→ * @description
    26→ * - `useFieldContext<T>()` - Access current field state inside custom field components
    27→ * - `useFormContext()` - Access form instance from anywhere in the form tree
    28→ * - `fieldContext` / `formContext` - Raw context objects (rarely needed)
    29→ *
    30→ * Use `useFieldContext` when building custom field components that need field state.
    31→ * Use `useFormContext` for custom components that need to read/write form state.
    32→ *
    33→ * @example
    34→ * // Custom field component using field context
    35→ * function CustomDatePicker(props: DatePickerProps) {
    36→ *   const field = useFieldContext<Date>();
    37→ *   return (
    38→ *     <DatePicker
    39→ *       value={field.state.value}
    40→ *       onChange={(date) => field.handleChange(date)}
    41→ *     />
    42→ *   );
    43→ * }
    44→ */
    45→export const { fieldContext, useFieldContext, formContext, useFormContext } =
    46→  createFormHookContexts();
    47→
    48→/**
    49→ * Form submit button with automatic loading state
    50→ *
    51→ * @description
    52→ * Shows loading spinner automatically when form is submitting.
    53→ * Use inside Form component or access via `form.SubmitButton` (preferred).
    54→ *
    55→ * @example
    56→ * // Preferred: Use via form instance
    57→ * <form.SubmitButton>Save</form.SubmitButton>
    58→ *
    59→ * // With size/variant props
    60→ * <form.SubmitButton size="lg" variant="outline">Create</form.SubmitButton>
    61→ */
    62→export function SubmitButton(props: React.ComponentProps<typeof Button>) {
    63→  const form = useFormContext();
    64→
    65→  return (
    66→    <form.Subscribe selector={(state) => state.isSubmitting}>
    67→      {(isSubmitting) => (
    68→        <LoadingButton type="submit" loading={isSubmitting} {...props} />
    69→      )}
    70→    </form.Subscribe>
