"use client";

import { Slider } from "@/components/ui/slider";
import { cn } from "@/lib/utils";

const moodEmojis = [
  { value: 0, emoji: "😰", label: "Tres mal" },
  { value: 1, emoji: "😢", label: "Mal" },
  { value: 2, emoji: "😞", label: "Pas bien" },
  { value: 3, emoji: "😕", label: "Difficile" },
  { value: 4, emoji: "😐", label: "Moyen" },
  { value: 5, emoji: "🙂", label: "Correct" },
  { value: 6, emoji: "😊", label: "Bien" },
  { value: 7, emoji: "😄", label: "Tres bien" },
  { value: 8, emoji: "😁", label: "Super" },
  { value: 9, emoji: "🤩", label: "Excellent" },
  { value: 10, emoji: "🌟", label: "Parfait" },
];

type MoodSliderProps = {
  value: number;
  onChange: (value: number) => void;
  showEmoji?: boolean;
  showLabel?: boolean;
  className?: string;
};

export function MoodSlider({
  value,
  onChange,
  showEmoji = true,
  showLabel = true,
  className,
}: MoodSliderProps) {
  const currentMood = moodEmojis[value] ?? moodEmojis[5];

  return (
    <div className={cn("flex flex-col gap-4", className)}>
      {showEmoji && (
        <div className="flex flex-col items-center gap-2">
          <span className="text-6xl transition-transform hover:scale-110">
            {currentMood.emoji}
          </span>
          {showLabel && (
            <span className="text-muted-foreground text-sm font-medium">
              {currentMood.label}
            </span>
          )}
        </div>
      )}
      <div className="relative px-2">
        <Slider
          value={[value]}
          onValueChange={(values) => onChange(values[0])}
          min={0}
          max={10}
          step={1}
          className="cursor-pointer"
        />
        <div className="mt-2 flex justify-between text-xs text-muted-foreground">
          <span>0</span>
          <span>5</span>
          <span>10</span>
        </div>
      </div>
    </div>
  );
}

export function getMoodEmoji(value: number): string {
  return moodEmojis[Math.round(value)]?.emoji ?? "🙂";
}

export function getMoodLabel(value: number): string {
  return moodEmojis[Math.round(value)]?.label ?? "Correct";
}

export function getMoodColor(value: number): string {
  if (value <= 2) return "text-red-500";
  if (value <= 4) return "text-orange-500";
  if (value <= 6) return "text-yellow-500";
  if (value <= 8) return "text-green-500";
  return "text-teal";
}

"use client";

import { Slider } from "@/components/ui/slider";
import { cn } from "@/lib/utils";
import { Battery, BatteryLow, BatteryMedium, BatteryFull, Zap } from "lucide-react";

const energyLevels = [
  { min: 0, max: 2, icon: BatteryLow, label: "Epuise", color: "text-red-500" },
  { min: 3, max: 4, icon: BatteryMedium, label: "Fatigue", color: "text-orange-500" },
  { min: 5, max: 6, icon: Battery, label: "Correct", color: "text-yellow-500" },
  { min: 7, max: 8, icon: BatteryFull, label: "Energique", color: "text-green-500" },
  { min: 9, max: 10, icon: Zap, label: "Dynamique", color: "text-teal" },
];

function getEnergyLevel(value: number) {
  return energyLevels.find((level) => value >= level.min && value <= level.max) ?? energyLevels[2];
}

type EnergySliderProps = {
  value: number;
  onChange: (value: number) => void;
  showIcon?: boolean;
  showLabel?: boolean;
  className?: string;
};

export function EnergySlider({
  value,
  onChange,
  showIcon = true,
  showLabel = true,
  className,
}: EnergySliderProps) {
  const currentLevel = getEnergyLevel(value);
  const Icon = currentLevel.icon;

  return (
    <div className={cn("flex flex-col gap-4", className)}>
      {showIcon && (
        <div className="flex flex-col items-center gap-2">
          <Icon className={cn("size-12", currentLevel.color)} />
          {showLabel && (
            <span className="text-muted-foreground text-sm font-medium">
              {currentLevel.label}
            </span>
          )}
        </div>
      )}
      <div className="relative px-2">
        <Slider
          value={[value]}
          onValueChange={(values) => onChange(values[0])}
          min={0}
          max={10}
          step={1}
          className="cursor-pointer"
        />
        <div className="mt-2 flex justify-between text-xs text-muted-foreground">
          <span>0</span>
          <span>5</span>
          <span>10</span>
        </div>
      </div>
    </div>
  );
}

export function getEnergyIcon(value: number) {
  return getEnergyLevel(value).icon;
}

export function getEnergyLabel(value: number): string {
  return getEnergyLevel(value).label;
}

export function getEnergyColor(value: number): string {
  return getEnergyLevel(value).color;
}

