  return energyLevels.find((level) => value >= level.min && value <= level.max) ?? energyLevels[2];
}

type EnergySliderProps = {
  value: number;
  onChange: (value: number) => void;
  showIcon?: boolean;
  showLabel?: boolean;
  className?: string;
};

export function EnergySlider({
  value,
  onChange,
  showIcon = true,
  showLabel = true,
  className,
}: EnergySliderProps) {
  const currentLevel = getEnergyLevel(value);
  const Icon = currentLevel.icon;

  return (
    <div className={cn("flex flex-col gap-4", className)}>
      {showIcon && (
        <div className="flex flex-col items-center gap-2">
          <Icon className={cn("size-12", currentLevel.color)} />
          {showLabel && (
            <span className="text-muted-foreground text-sm font-medium">
              {currentLevel.label}
            </span>
          )}
        </div>
      )}
      <div className="relative px-2">
        <Slider
          value={[value]}
          onValueChange={(values) => onChange(values[0])}
          min={0}
          max={10}
          step={1}
          className="cursor-pointer"
        />
        <div className="mt-2 flex justify-between text-xs text-muted-foreground">
          <span>0</span>
          <span>5</span>
          <span>10</span>
        </div>
      </div>
    </div>
  );
}

export function getEnergyIcon(value: number) {
  return getEnergyLevel(value).icon;
}

export function getEnergyLabel(value: number): string {
  return getEnergyLevel(value).label;
}

export function getEnergyColor(value: number): string {
  return getEnergyLevel(value).color;
}

