"use server";

import { authAction } from "@/lib/actions/safe-actions";
import { prisma } from "@/lib/prisma";
import { z } from "zod";

const CreateMoodEntrySchema = z.object({
  value: z.number().min(0).max(10),
  energy: z.number().min(0).max(10).optional(),
  anxiety: z.number().min(0).max(10).optional(),
  note: z.string().optional(),
  context: z.array(z.string()).optional(),
});

export const createMoodEntryAction = authAction
  .inputSchema(CreateMoodEntrySchema)
  .action(async ({ parsedInput, ctx }) => {
    const entry = await prisma.moodEntry.create({
      data: {
        userId: ctx.user.id,
        value: parsedInput.value,
        energy: parsedInput.energy,
        anxiety: parsedInput.anxiety,
        note: parsedInput.note,
        context: parsedInput.context ?? [],
      },
    });

    return { success: true, entryId: entry.id };
  });

export const getTodaysMoodAction = authAction.action(async ({ ctx }) => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const entry = await prisma.moodEntry.findFirst({
    where: {
      userId: ctx.user.id,
      createdAt: {
        gte: today,
      },
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  return entry;
});

export const getMoodHistoryAction = authAction
  .inputSchema(
    z.object({
      days: z.number().min(1).max(90).default(7),
    }),
  )
  .action(async ({ parsedInput, ctx }) => {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - parsedInput.days);
    startDate.setHours(0, 0, 0, 0);

    const entries = await prisma.moodEntry.findMany({
      where: {
        userId: ctx.user.id,
        createdAt: {
          gte: startDate,
        },
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    return entries;
  });

export const getMoodStreakAction = authAction.action(async ({ ctx }) => {
  const entries = await prisma.moodEntry.findMany({
    where: {
      userId: ctx.user.id,
    },
    orderBy: {
      createdAt: "desc",
    },
    select: {
      createdAt: true,
    },
  });

  if (entries.length === 0) return 0;

  let streak = 0;
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Check if there's an entry today
  const hasEntryToday = entries.some((entry) => {
    const entryDate = new Date(entry.createdAt);
    entryDate.setHours(0, 0, 0, 0);
    return entryDate.getTime() === today.getTime();
  });

  if (!hasEntryToday) return 0;

  // Count consecutive days
  const entryDates = new Set(
    entries.map((entry) => {
      const date = new Date(entry.createdAt);
      date.setHours(0, 0, 0, 0);
      return date.getTime();
    }),
  );

  let currentDate = today.getTime();
  while (entryDates.has(currentDate)) {
    streak++;
    currentDate -= 24 * 60 * 60 * 1000; // Go back one day
  }

  return streak;
});

"use client";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { Check, Loader2, Moon, Plus } from "lucide-react";
import { useTranslations } from "next-intl";
import { useState, useTransition } from "react";
import { EnergySlider } from "./energy-slider";
import { MoodSlider } from "./mood-slider";
import { createMoodEntryAction } from "./mood.action";

type QuickEntryModalProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
};

const contextTags = [
  { id: "work", icon: "💼" },
  { id: "family", icon: "👨‍👩‍👧" },
  { id: "health", icon: "🏥" },
  { id: "social", icon: "👥" },
  { id: "exercise", icon: "🏃" },
  { id: "weather", icon: "☀️" },
  { id: "stress", icon: "😤" },
  { id: "sleep", icon: "😴" },
];

export function QuickEntryModal({
  open,
  onOpenChange,
  onSuccess,
}: QuickEntryModalProps) {
  const t = useTranslations("QuickEntry");
  const tMood = useTranslations("Mood");
  const tCommon = useTranslations("Common");

  const [isPending, startTransition] = useTransition();
  const [step, setStep] = useState<"mood" | "details" | "done">("mood");

  // Form state
  const [mood, setMood] = useState(5);
  const [energy, setEnergy] = useState(5);
  const [sleepHours, setSleepHours] = useState<string>("");
  const [note, setNote] = useState("");
  const [selectedContext, setSelectedContext] = useState<string[]>([]);

  const handleSubmit = () => {
    startTransition(async () => {
      await createMoodEntryAction({
        value: mood,
        energy,
        note: note || undefined,
        context: selectedContext,
      });
      setStep("done");
      setTimeout(() => {
        onOpenChange(false);
        onSuccess?.();
        // Reset form
        setStep("mood");
        setMood(5);
        setEnergy(5);
        setSleepHours("");
        setNote("");
        setSelectedContext([]);
      }, 1500);
    });
  };

  const toggleContext = (id: string) => {
    setSelectedContext((prev) =>
      prev.includes(id) ? prev.filter((c) => c !== id) : [...prev, id],
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{t("title")}</DialogTitle>
          <DialogDescription>{t("subtitle")}</DialogDescription>
        </DialogHeader>

        {step === "mood" && (
          <div className="flex flex-col gap-6 py-4">
            <div>
              <Label className="mb-4 block text-center text-sm font-medium">
                {t("moodQuestion")}
              </Label>
              <MoodSlider value={mood} onChange={setMood} />
            </div>

            <div>
              <Label className="mb-4 block text-center text-sm font-medium">
                {t("energyQuestion")}
              </Label>
              <EnergySlider value={energy} onChange={setEnergy} />
            </div>

            <DialogFooter className="flex-row gap-2 sm:justify-between">
              <Button
                variant="ghost"
                onClick={() => onOpenChange(false)}
                className="flex-1"
              >
                {tCommon("cancel")}
              </Button>
              <Button onClick={() => setStep("details")} className="flex-1">
                {tCommon("next")}
              </Button>
            </DialogFooter>
          </div>
        )}

        {step === "details" && (
          <div className="flex flex-col gap-6 py-4">
            <div>
              <Label htmlFor="sleep" className="mb-2 flex items-center gap-2">
                <Moon className="size-4" />
                {t("sleepQuestion")}
              </Label>
              <Input
                id="sleep"
                type="number"
                min={0}
                max={24}
                step={0.5}
                placeholder="7.5"
                value={sleepHours}
                onChange={(e) => setSleepHours(e.target.value)}
                className="text-center text-lg"
              />
            </div>

            <div>
              <Label className="mb-2 block">{tMood("context")}</Label>
              <div className="flex flex-wrap gap-2">
                {contextTags.map((tag) => (
                  <Button
                    key={tag.id}
                    variant={
                      selectedContext.includes(tag.id) ? "default" : "outline"
                    }
                    size="sm"
                    onClick={() => toggleContext(tag.id)}
                    className={cn(
                      "gap-1",
                      selectedContext.includes(tag.id) && "bg-teal text-white",
                    )}
                  >
                    <span>{tag.icon}</span>
                    <span>{tMood(tag.id as keyof IntlMessages["Mood"])}</span>
                  </Button>
                ))}
              </div>
            </div>

            <div>
              <Label htmlFor="note" className="mb-2 block">
                {tMood("addNote")}
              </Label>
              <Textarea
                id="note"
                placeholder={tMood("notePlaceholder")}
                value={note}
                onChange={(e) => setNote(e.target.value)}
                rows={3}
              />
            </div>

            <DialogFooter className="flex-row gap-2 sm:justify-between">
              <Button
                variant="ghost"
                onClick={() => setStep("mood")}
                className="flex-1"
              >
                {tCommon("back")}
              </Button>
              <Button
                onClick={handleSubmit}
                disabled={isPending}
                className="flex-1 bg-teal hover:bg-teal-dark"
              >
                {isPending ? (
                  <Loader2 className="size-4 animate-spin" />
                ) : (
                  <>
                    <Check className="size-4" />
                    {t("done")}
                  </>
                )}
              </Button>
            </DialogFooter>
          </div>
        )}

        {step === "done" && (
          <div className="flex flex-col items-center gap-4 py-8">
            <div className="flex size-16 items-center justify-center rounded-full bg-teal/20">
              <Check className="size-8 text-teal" />
            </div>
            <p className="text-lg font-medium">{tCommon("success")}</p>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

export function QuickEntryButton() {
  const [open, setOpen] = useState(false);
  const t = useTranslations("Dashboard");

  return (
    <>
      <Button
        onClick={() => setOpen(true)}
        size="lg"
        className="fixed right-4 bottom-20 z-50 size-14 rounded-full bg-teal shadow-lg hover:bg-teal-dark md:bottom-8"
      >
        <Plus className="size-6" />
        <span className="sr-only">{t("quickEntry")}</span>
      </Button>
      <QuickEntryModal open={open} onOpenChange={setOpen} />
    </>
  );
}

export { MoodSlider, getMoodEmoji, getMoodLabel, getMoodColor } from "./mood-slider";
export { EnergySlider, getEnergyIcon, getEnergyLabel, getEnergyColor } from "./energy-slider";
export { QuickEntryModal, QuickEntryButton } from "./quick-entry-modal";
export {
  createMoodEntryAction,
  getTodaysMoodAction,
  getMoodHistoryAction,
  getMoodStreakAction,
} from "./mood.action";

