  const [sleepHours, setSleepHours] = useState<string>("");
  const [note, setNote] = useState("");
  const [selectedContext, setSelectedContext] = useState<string[]>([]);

  const handleSubmit = () => {
    startTransition(async () => {
      await createMoodEntryAction({
        value: mood,
        energy,
        note: note || undefined,
        context: selectedContext,
      });
      setStep("done");
      setTimeout(() => {
        onOpenChange(false);
        onSuccess?.();
        // Reset form
        setStep("mood");
        setMood(5);
        setEnergy(5);
        setSleepHours("");
        setNote("");
        setSelectedContext([]);
      }, 1500);
    });
  };

  const toggleContext = (id: string) => {
    setSelectedContext((prev) =>
      prev.includes(id) ? prev.filter((c) => c !== id) : [...prev, id],
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{t("title")}</DialogTitle>
          <DialogDescription>{t("subtitle")}</DialogDescription>
        </DialogHeader>

        {step === "mood" && (
          <div className="flex flex-col gap-6 py-4">
            <div>
              <Label className="mb-4 block text-center text-sm font-medium">
                {t("moodQuestion")}
              </Label>
              <MoodSlider value={mood} onChange={setMood} />
            </div>

            <div>
              <Label className="mb-4 block text-center text-sm font-medium">
                {t("energyQuestion")}
              </Label>
              <EnergySlider value={energy} onChange={setEnergy} />
            </div>

            <DialogFooter className="flex-row gap-2 sm:justify-between">
              <Button
                variant="ghost"
                onClick={() => onOpenChange(false)}
                className="flex-1"
              >
                {tCommon("cancel")}
              </Button>
              <Button onClick={() => setStep("details")} className="flex-1">
                {tCommon("next")}
              </Button>
            </DialogFooter>
          </div>
        )}

        {step === "details" && (
          <div className="flex flex-col gap-6 py-4">
            <div>
              <Label htmlFor="sleep" className="mb-2 flex items-center gap-2">
                <Moon className="size-4" />
                {t("sleepQuestion")}
              </Label>
              <Input
                id="sleep"
                type="number"
                min={0}
                max={24}
                step={0.5}
                placeholder="7.5"
                value={sleepHours}
                onChange={(e) => setSleepHours(e.target.value)}
                className="text-center text-lg"
              />
            </div>

            <div>
              <Label className="mb-2 block">{tMood("context")}</Label>
              <div className="flex flex-wrap gap-2">
                {contextTags.map((tag) => (
                  <Button
                    key={tag.id}
                    variant={
                      selectedContext.includes(tag.id) ? "default" : "outline"
                    }
                    size="sm"
                    onClick={() => toggleContext(tag.id)}
                    className={cn(
                      "gap-1",
                      selectedContext.includes(tag.id) && "bg-teal text-white",
                    )}
                  >
                    <span>{tag.icon}</span>
                    <span>{tMood(tag.id as keyof IntlMessages["Mood"])}</span>
                  </Button>
                ))}
              </div>
            </div>

            <div>
              <Label htmlFor="note" className="mb-2 block">
                {tMood("addNote")}
              </Label>
              <Textarea
                id="note"
                placeholder={tMood("notePlaceholder")}
                value={note}
                onChange={(e) => setNote(e.target.value)}
                rows={3}
              />
            </div>

            <DialogFooter className="flex-row gap-2 sm:justify-between">
              <Button
                variant="ghost"
                onClick={() => setStep("mood")}
                className="flex-1"
              >
                {tCommon("back")}
              </Button>
              <Button
                onClick={handleSubmit}
                disabled={isPending}
                className="bg-teal hover:bg-teal-dark flex-1"
              >
                {isPending ? (
                  <Loader2 className="size-4 animate-spin" />
                ) : (
                  <>
                    <Check className="size-4" />
                    {t("done")}
                  </>
                )}
              </Button>
            </DialogFooter>
          </div>
        )}

        {step === "done" && (
          <div className="flex flex-col items-center gap-4 py-8">
            <div className="bg-teal/20 flex size-16 items-center justify-center rounded-full">
              <Check className="text-teal size-8" />
            </div>
            <p className="text-lg font-medium">{tCommon("success")}</p>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

export function QuickEntryButton() {
  const [open, setOpen] = useState(false);
  const t = useTranslations("Dashboard");

  return (
    <>
      <Button
        onClick={() => setOpen(true)}
        size="lg"
        className="bg-teal hover:bg-teal-dark fixed right-4 bottom-20 z-50 size-14 rounded-full shadow-lg md:bottom-8"
      >
        <Plus className="size-6" />
        <span className="sr-only">{t("quickEntry")}</span>
      </Button>
      <QuickEntryModal open={open} onOpenChange={setOpen} />
    </>
  );
}

