            >
              <Icon
                className={cn("size-5", isActive && "text-teal")}
                strokeWidth={isActive ? 2.5 : 2}
              />
              <span className="font-medium">
                {t(item.labelKey as keyof IntlMessages["Navigation"])}
              </span>
            </Link>
          );
        })}
      </div>
    </nav>
  );
}

