"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { Smile } from "lucide-react";
import { useTranslations } from "next-intl";

const moodEmojis: Record<number, { emoji: string; color: string }> = {
  0: { emoji: "😰", color: "text-red-600" },
  1: { emoji: "😢", color: "text-red-500" },
  2: { emoji: "😞", color: "text-orange-600" },
  3: { emoji: "😔", color: "text-orange-500" },
  4: { emoji: "😐", color: "text-yellow-600" },
  5: { emoji: "🙂", color: "text-yellow-500" },
  6: { emoji: "😊", color: "text-lime-500" },
  7: { emoji: "😄", color: "text-green-500" },
  8: { emoji: "😁", color: "text-green-600" },
  9: { emoji: "🤩", color: "text-emerald-500" },
  10: { emoji: "🌟", color: "text-emerald-600" },
};

type MoodSummaryCardProps = {
  latestMood: {
    value: number;
    energy?: number | null;
    createdAt: Date;
  } | null;
};

export function MoodSummaryCard({ latestMood }: MoodSummaryCardProps) {
  const t = useTranslations("Dashboard");

  const moodData = latestMood ? moodEmojis[latestMood.value] : null;

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium">{t("moodToday")}</CardTitle>
        <Smile className="text-muted-foreground size-4" />
      </CardHeader>
      <CardContent>
        {latestMood ? (
          <div className="flex items-center gap-3">
            <span className="text-4xl">{moodData?.emoji}</span>
            <div className="flex flex-col">
              <span className={cn("text-2xl font-bold", moodData?.color)}>
                {latestMood.value}/10
              </span>
              {latestMood.energy !== null && latestMood.energy !== undefined && (
                <span className="text-muted-foreground text-xs">
                  {t("energy")}: {latestMood.energy}/10
                </span>
              )}
            </div>
          </div>
        ) : (
          <div className="text-muted-foreground py-2">
            <p className="text-sm">{t("noMoodRecorded")}</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

