"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { Check, Pill } from "lucide-react";
import { useTranslations } from "next-intl";
import Link from "next/link";

type MedicationItem = {
  id: string;
  name: string;
  dosage: string;
  timeSlot: string;
  taken: boolean;
};

type MedicationsTodayCardProps = {
  medications: MedicationItem[];
  totalCount: number;
  takenCount: number;
};

export function MedicationsTodayCard({
  medications,
  totalCount,
  takenCount,
}: MedicationsTodayCardProps) {
  const t = useTranslations("Dashboard");

  const progress = totalCount > 0 ? (takenCount / totalCount) * 100 : 0;

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium">
          {t("medicationsToday")}
        </CardTitle>
        <Pill className="text-teal size-4" />
      </CardHeader>
      <CardContent>
        <div className="mb-3 flex items-baseline gap-2">
          <span className="text-2xl font-bold">
            {takenCount}/{totalCount}
          </span>
          <span className="text-muted-foreground text-sm">{t("taken")}</span>
        </div>

        <div className="bg-muted mb-3 h-2 w-full overflow-hidden rounded-full">
          <div
            className="bg-teal h-full rounded-full transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>

        {medications.length > 0 ? (
          <div className="space-y-2">
            {medications.slice(0, 3).map((med) => (
              <div
                key={med.id}
                className={cn(
                  "flex items-center justify-between rounded-md p-2 text-sm",
                  med.taken ? "bg-muted/50" : "bg-muted"
                )}
              >
                <div className="flex flex-col">
                  <span
                    className={cn(
                      "font-medium",
                      med.taken && "text-muted-foreground line-through"
                    )}
                  >
                    {med.name}
                  </span>
                  <span className="text-muted-foreground text-xs">
                    {med.dosage} - {med.timeSlot}
                  </span>
                </div>
                {med.taken && <Check className="text-teal size-4" />}
              </div>
            ))}
          </div>
        ) : (
          <p className="text-muted-foreground text-sm">
            {t("noMedicationsToday")}
          </p>
        )}

        <Button variant="link" className="mt-2 h-auto p-0" asChild>
          <Link href="/medications">{t("viewAll")}</Link>
        </Button>
      </CardContent>
    </Card>
  );
}

