"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Moon } from "lucide-react";
import { useTranslations } from "next-intl";

type SleepSummaryCardProps = {
  lastNight: {
    hours: number;
    quality: number;
  } | null;
  weeklyAverage: number | null;
};

export function SleepSummaryCard({
  lastNight,
  weeklyAverage,
}: SleepSummaryCardProps) {
  const t = useTranslations("Dashboard");

  const formatHours = (hours: number) => {
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    return `${h}h${m > 0 ? ` ${m}m` : ""}`;
  };

  const getQualityLabel = (quality: number): string => {
    if (quality >= 8) return t("sleepQuality.excellent");
    if (quality >= 6) return t("sleepQuality.good");
    if (quality >= 4) return t("sleepQuality.average");
    return t("sleepQuality.poor");
  };

  const getQualityColor = (quality: number): string => {
    if (quality >= 8) return "text-emerald-500";
    if (quality >= 6) return "text-green-500";
    if (quality >= 4) return "text-yellow-500";
    return "text-red-500";
  };

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium">{t("sleepLastNight")}</CardTitle>
        <Moon className="size-4 text-indigo-500" />
      </CardHeader>
      <CardContent>
        {lastNight ? (
          <>
            <div className="flex items-baseline gap-2">
              <span className="text-3xl font-bold">
                {formatHours(lastNight.hours)}
              </span>
            </div>
            <p className={`mt-1 text-sm font-medium ${getQualityColor(lastNight.quality)}`}>
              {getQualityLabel(lastNight.quality)}
            </p>
            {weeklyAverage !== null && (
              <p className="text-muted-foreground mt-2 text-xs">
                {t("weeklyAverage")}: {formatHours(weeklyAverage)}
              </p>
            )}
          </>
        ) : (
          <div className="text-muted-foreground py-2">
            <p className="text-sm">{t("noSleepRecorded")}</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

