"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { Check, Clock, MoreHorizontal, X } from "lucide-react";
import { useTranslations } from "next-intl";

type TimeSlotStatus = "taken" | "skipped" | "pending" | "upcoming";

type TimeSlot = {
  time: string;
  status: TimeSlotStatus;
};

type MedicationCardProps = {
  id: string;
  name: string;
  dosage: string;
  instructions?: string | null;
  isPRN: boolean;
  timeSlots: TimeSlot[];
  onMarkTaken?: (id: string, time: string) => void;
  onMarkSkipped?: (id: string, time: string) => void;
};

export function MedicationCard({
  name,
  dosage,
  instructions,
  isPRN,
  timeSlots,
}: MedicationCardProps) {
  const t = useTranslations("Medications");

  const getStatusIcon = (status: TimeSlotStatus) => {
    switch (status) {
      case "taken":
        return <Check className="size-4 text-green-500" />;
      case "skipped":
        return <X className="size-4 text-red-500" />;
      case "pending":
        return <Clock className="text-teal size-4" />;
      default:
        return <Clock className="text-muted-foreground size-4" />;
    }
  };

  const getStatusColor = (status: TimeSlotStatus) => {
    switch (status) {
      case "taken":
        return "bg-green-50 border-green-200 dark:bg-green-950/20 dark:border-green-800";
      case "skipped":
        return "bg-red-50 border-red-200 dark:bg-red-950/20 dark:border-red-800";
      case "pending":
        return "bg-teal/10 border-teal/30";
      default:
        return "bg-muted border-muted-foreground/20";
    }
  };

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <div className="flex flex-col">
          <CardTitle className="text-base font-semibold">{name}</CardTitle>
          <p className="text-muted-foreground text-sm">{dosage}</p>
        </div>
        <div className="flex items-center gap-2">
          {isPRN && (
            <span className="bg-lavender/50 text-lavender-foreground rounded-full px-2 py-0.5 text-xs font-medium">
              PRN
            </span>
          )}
          <Button variant="ghost" size="icon" className="size-8">
            <MoreHorizontal className="size-4" />
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {instructions && (
          <p className="text-muted-foreground mb-3 text-sm">{instructions}</p>
        )}

        <div className="flex flex-wrap gap-2">
          {timeSlots.map((slot, index) => (
            <div
              key={index}
              className={cn(
                "flex items-center gap-1.5 rounded-full border px-3 py-1",
                getStatusColor(slot.status)
              )}
            >
              {getStatusIcon(slot.status)}
              <span className="text-sm font-medium">{slot.time}</span>
            </div>
          ))}
        </div>

        {timeSlots.some((slot) => slot.status === "pending") && (
          <div className="mt-3 flex gap-2">
            <Button size="sm" className="bg-teal hover:bg-teal/90">
              {t("markAsTaken")}
            </Button>
            <Button size="sm" variant="outline">
              {t("skipped")}
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

