"use client";

import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { Moon } from "lucide-react";
import { useTranslations } from "next-intl";

type SleepEntryCardProps = {
  date: Date;
  bedTime: string;
  wakeTime: string;
  duration: number;
  quality: number;
};

export function SleepEntryCard({
  date,
  bedTime,
  wakeTime,
  duration,
  quality,
}: SleepEntryCardProps) {
  const t = useTranslations("Sleep");

  const formatDate = (d: Date) => {
    return d.toLocaleDateString("fr-FR", {
      weekday: "short",
      day: "numeric",
      month: "short",
    });
  };

  const formatDuration = (hours: number) => {
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    return `${h}h${m > 0 ? ` ${m}m` : ""}`;
  };

  const getQualityLabel = (q: number): string => {
    if (q >= 8) return t("excellent");
    if (q >= 6) return t("goodQuality");
    if (q >= 4) return t("fair");
    return t("poor");
  };

  const getQualityColor = (q: number): string => {
    if (q >= 8) return "text-emerald-500";
    if (q >= 6) return "text-green-500";
    if (q >= 4) return "text-yellow-500";
    return "text-red-500";
  };

  const getQualityBg = (q: number): string => {
    if (q >= 8) return "bg-emerald-50 dark:bg-emerald-950/20";
    if (q >= 6) return "bg-green-50 dark:bg-green-950/20";
    if (q >= 4) return "bg-yellow-50 dark:bg-yellow-950/20";
    return "bg-red-50 dark:bg-red-950/20";
  };

  return (
    <Card className={cn("overflow-hidden", getQualityBg(quality))}>
      <CardContent className="p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-background flex size-10 items-center justify-center rounded-full">
              <Moon className="size-5 text-indigo-500" />
            </div>
            <div>
              <p className="font-medium">{formatDate(date)}</p>
              <p className="text-muted-foreground text-sm">
                {bedTime} - {wakeTime}
              </p>
            </div>
          </div>

          <div className="text-right">
            <p className="text-xl font-bold">{formatDuration(duration)}</p>
            <p className={cn("text-sm font-medium", getQualityColor(quality))}>
              {getQualityLabel(quality)}
            </p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

