"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { SleepEntryCard } from "@/features/sleep";
import { useTranslations } from "next-intl";
import { useMemo } from "react";

export function SleepContent() {
  const t = useTranslations("Sleep");

  // TODO: Fetch real data from the database
  const sleepEntries = useMemo(() => {
    const now = Date.now();
    return [
      {
        id: "1",
        date: new Date(now),
        bedTime: "23:30",
        wakeTime: "07:00",
        duration: 7.5,
        quality: 7,
      },
      {
        id: "2",
        date: new Date(now - 86400000),
        bedTime: "00:15",
        wakeTime: "06:45",
        duration: 6.5,
        quality: 5,
      },
      {
        id: "3",
        date: new Date(now - 86400000 * 2),
        bedTime: "22:45",
        wakeTime: "07:15",
        duration: 8.5,
        quality: 9,
      },
      {
        id: "4",
        date: new Date(now - 86400000 * 3),
        bedTime: "01:00",
        wakeTime: "07:30",
        duration: 6.5,
        quality: 4,
      },
    ];
  }, []);

  const averageDuration =
    sleepEntries.reduce((acc, entry) => acc + entry.duration, 0) /
    sleepEntries.length;

  const averageQuality =
    sleepEntries.reduce((acc, entry) => acc + entry.quality, 0) /
    sleepEntries.length;

  const formatDuration = (hours: number) => {
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    return `${h}h${m > 0 ? ` ${m}m` : ""}`;
  };

  return (
    <div className="flex flex-col gap-6">
      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">
              {t("averageDuration")}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">
              {formatDuration(averageDuration)}
            </p>
            <p className="text-muted-foreground text-sm">{t("lastWeek")}</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">
              {t("quality")}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">{averageQuality.toFixed(1)}/10</p>
            <p className="text-muted-foreground text-sm">{t("lastWeek")}</p>
          </CardContent>
        </Card>
      </div>

      <div className="flex flex-col gap-3">
        <h2 className="text-lg font-semibold">{t("lastWeek")}</h2>
        {sleepEntries.map((entry) => (
          <SleepEntryCard
            key={entry.id}
            date={entry.date}
            bedTime={entry.bedTime}
            wakeTime={entry.wakeTime}
            duration={entry.duration}
            quality={entry.quality}
          />
        ))}
      </div>
    </div>
  );
}

